  'terms.provider.lead': 'Hevalo لەلایەن ئەمەوە پێشکەش دەکرێت:',
  'terms.warranty.title': 'تەنها ئەوە بڵاو بکەرەوە کە ڕێگەت هەیە',
  'terms.warranty.body':
    'کاتێک شتێک بڵاو دەکەیتەوە، بەڵێن دەدەیت کە خۆت دروستت کردووە، یان ڕێگەت هەیە بڵاوی بکەیتەوە: ئازادە بۆ بەکارهێنان، مۆڵەتت هەیە، یان یاسا ڕێگە دەدات — وەک وتەیەکی کورت لەگەڵ سەرچاوەکەی. وێنە، هونەر، وشەی گۆرانی یان وەرگێڕانی کەسانی تر بێ مۆڵەت بڵاو مەکەرەوە.',
  'terms.licence.title': 'چی ڕێگەیەکمان پێ دەدەیت',
  'terms.licence.body':
    'بۆ کارپێکردنی Hevalo، پێویستە ئەوەی بڵاوی دەکەیتەوە هەڵیبگرین، کۆپی بکەین (قەبارەی بچووکتر، پاشەکەوت، کۆپی لەسەر ئەو سێرڤەرانەی دەیگەیەنن) و بەو کەسانەی پیشان بدەین کە ڕێکخستنەکانت ڕێگە دەدەن. تەنها ئەمەیە: نایفرۆشین و لە ڕیکلامدا بەکاری ناهێنین. کاتێک دەیسڕیتەوە کۆتایی دێت، جگە لە پاشەکەوت و ئەو کۆپیانەی یاسا داوامان لێ دەکات بۆ ماوەیەکی کورت بیانهێڵینەوە.',
  'terms.notices.title': 'ئاگادارکردنەوەکانی مافی بڵاوکردنەوە',
  'terms.notices.body':
    'هەر کەسێک پێی وابێت شتێک لێرە کارەکەی کۆپی دەکات، دەتوانێت لە پەڕەی مافی بڵاوکردنەوە، بێ هەژمار، پێمان بڵێت. ئەگەر بەهۆی ئاگادارکردنەوەیەکەوە پۆستەکەت لاببەین، هۆکارەکەت پێ دەڵێین، و دەتوانیت وەڵامی دژ بنێریت یان داوای پێداچوونەوە بکەیت.',
  'terms.notices.link': 'بڕۆ بۆ پەڕەی مافی بڵاوکردنەوە',
  'terms.moderationHow':
    'کاتێک شتێک لادەبەین یان هەژمارەکەت سنووردار دەکەین، پێت دەڵێین بۆچی و کام یاسا شکێندرا. ڕاپۆرت و ئاگادارکردنەوەکانی مافی بڵاوکردنەوە لەلایەن کەسێکەوە بڕیاریان لەسەر دەدرێت؛ هەندێک پشکنین، وەک سنووری بڵاوکردنەوەی زۆر خێرا، خۆکارن. دەتوانیت لە ماوەی شەش مانگدا لە دۆخی هەژمارەوە داوای پێداچوونەوە بکەیت.',
  'terms.repeat.title': 'کۆپیکردنی دووبارە',
  'terms.repeat.body':
    'ئەگەر لە ماوەی دوازدە مانگدا سێ ئاگادارکردنەوەی مافی بڵاوکردنەوە دژی پۆستەکانت پەسەند بکرێن، لەوانەیە هەژمارەکەت دابخەین. لابردنێک کە دوای پێداچوونەوە یان وەڵامی دژ هەڵوەشێنرایەوە، هەژمار ناکرێت.',
  'terms.shopArt.title': 'شتەکانی فرۆشگا',
  'terms.shopArt.body':
    'پاشبنەما و ئایکۆنەکانی فرۆشگا وێنەن بۆ پرۆفایلەکەت، لەلایەن Hevaloوە دروستکراون. لەوانەیە شتێک دووبارە بکێشینەوە یان لە فرۆشگا دەری بهێنین. شتەکانی تۆ هی خۆت دەمێننەوە، بە وێنە نوێیەکەوە، و کاتێک ئەو شتانە دەگۆڕین کە کڕیوتن، پێت دەڵێین.',
  'terms.contact.title': 'چۆن پەیوەندیمان پێوە بکەیت',
  'terms.contact.lead': 'بە هەر یەکێک لەو زمانانەی خوارەوە بۆمان بنووسە. کەسێک وەڵام دەداتەوە.',
  'terms.law.title': 'کام یاسا جێبەجێ دەکرێت',
