  'games.wordle.name': 'وۆردڵی کوردی',
  'games.wordle.body': 'وشە کوردییەکە لە شەش هەوڵدا بدۆزەرەوە — بە تەنها، یان لە پێشبڕکێدا لەگەڵ هاوڕێیەک.',
