  'alphabet.summary.ckb': 'لە ڕاستەوە بۆ چەپ. زۆربەی پیتەکان بە پیتی دواتر دەلکێن.',
  'alphabet.group.watch': 'ناسراون، بەڵام جیاواز دەخوێنرێنەوە',
  'alphabet.group.watchBody': 'شێوەی ناسراو، دەنگی نوێ. لێرەوە دەست پێ بکە.',
