  'alphabet.group.vowelsBodyKmr': 'هەشت بزوێن، هەر یەکەیان هەمیشە بە یەک شێوە دەگوترێت.',
  'alphabet.group.vowelsBodyCkb': 'هەموویان دەنووسرێن، بە پێچەوانەی عەرەبی. و و ی هەم بزوێنن هەم نەبزوێن.',
  'alphabet.group.consonants': 'نەبزوێنەکان',
