  'alphabet.join.title': 'پیتەکان بە یەکەوە دەلکێن',
  'alphabet.join.body': 'Kurdî، پیت بە پیت، پاشان لکاو. شێوە بە پێی شوێن دەگۆڕێت.',
  'alphabet.tileLabel': '{letter}، وەک {hint}',
